/* Generates docs/contracts/mouse_slot_vectors.json from the real encoders of
 * main/comm/rf (host build, -DTEST_HOST). Run scripts/gen_mouse_slot_vectors.sh;
 * the test test_mouse_slot_vectors.c holds the same bytes. */
#include <stdio.h>
#include "rf_packet.h"
#include "rf_slot.h"
static void hex(const char *name, const uint8_t *b, unsigned n){ printf("    \"%s\": \"", name); for(unsigned i=0;i<n;i++) printf("%s%02x", i?" ":"", b[i]); printf("\""); }
int main(void){
  uint8_t b[32]; unsigned n;
  printf("{\n  \"comment\": \"Golden vectors generated by firmware/main/comm/rf/rf_packet.h + rf_pairing.c (host build). Bytes are the ESB payload, hex, in wire order.\",\n");
  printf("  \"radio\": {\"data_rate_bps\": 1000000, \"rf_setup\": \"0x06\", \"crc_bytes\": 2, \"address_bytes\": 5, \"dpl\": true, \"ack_payload\": true, \"pipe\": 0, \"mouse_setup_retr\": \"0x00\", \"dongle_setup_retr\": \"0x1f\"},\n");
  printf("  \"factory\": {\"address\": \"4b 61 53 65 02\", \"address_ascii\": \"KaSe\\\\x02\", \"channel\": \"0x52\", \"channel_mhz\": 2482},\n");
  printf("  \"rendezvous\": {\"address\": \"4b 53 50 52 ff\", \"address_ascii\": \"KSPR\\\\xff\", \"channel\": \"0x28\", \"channel_mhz\": 2440},\n");
  printf("  \"timings_ms\": {\"status_period\": %u, \"rearm_silence\": %u, \"link_lost\": %u, \"pair_window\": 120000, \"pair_listen_per_attempt\": 300, \"pair_attempts\": 20, \"pair_retry_gap\": 200},\n", RF_STATUS_PERIOD_MS, RF_REARM_SILENCE_MS, RF_LINK_LOST_MS);
  printf("  \"frames\": {\n");
  n = rf_encode_hidreport_mouse(b, 0x01, 5, -3, 0);        hex("hid_mouse_left_dx5_dym3", b, n); printf(",\n");
  n = rf_encode_hidreport_mouse(b, 0x00, 0, 0, 0);         hex("hid_mouse_idle_all_zero", b, n); printf(",\n");
  n = rf_encode_hidreport_mouse(b, 0x07, 127, -128, 1);    hex("hid_mouse_all_buttons_dx127_dym128_wheel1", b, n); printf(",\n");
  uint8_t mac[6] = {0xaa,0xbb,0xcc,0x11,0x22,0x33};
  n = rf_encode_pair_req2(b, mac, 0x02, RF_DEV_MOUSE);     hex("pair_req_v2_mac_aabbcc112233_slot2_devmouse", b, n); printf(",\n");
  rf_pair_ack_t a = { .set_id = 0xBEEF, .slot = 0x02 }; uint8_t dm[6]={0xac,0xa7,0x04,0x18,0x82,0x24}; memcpy(a.dongle_wifi_mac, dm, 6);
  n = rf_encode_pair_ack(b, &a);                            hex("pair_ack_setid_beef_dongle_aca704188224_slot2", b, n); printf("\n  },\n");
  /* pairing derivation */
  uint16_t id = crc16_ccitt(dm, 6);
  uint8_t addr[4], suf, ch; rf_derive_addr(id, 0x02, addr, &suf, &ch);
  printf("  \"derivation\": {\n    \"dongle_mac\": \"ac a7 04 18 82 24\",\n    \"set_id_crc16_ccitt_false\": \"0x%04x\",\n    \"mouse_address\": \"%02x %02x %02x %02x %02x\",\n    \"mouse_channel\": \"0x%02x\",\n    \"mouse_channel_mhz\": %u,\n    \"rule\": \"addr = 'K','S',set_id>>8,set_id&0xff,slot ; base_ch = 80 + 2*(set_id %% 20) ; ch = base_ch + (slot==2 ? 1 : 0) ; set_id 0x0000/0xffff -> 0x0001\"\n  },\n", id, addr[0],addr[1],addr[2],addr[3],suf, ch, 2400u+ch);
  printf("  \"crc16_ccitt_false_check\": {\"input_ascii\": \"123456789\", \"expected\": \"0x%04x\"}\n}\n", crc16_ccitt((const uint8_t*)"123456789", 9));
  return 0;
}
